    {
      "id": "C04",
      "name": "胡二爷",
      "role": "搅局配角",
      "arc": "自来熟的货郎，每集戳一个人的痛处，自己反而是藏得最深的",
      "from": [
        "原著胡二爷",
        "合并：岸边问路的路人甲乙"
      ],
      "tier": "support"
    },
    {
      "id": "C05",
      "name": "岸上挑灯的更夫",
      "tier": "functional",
      "role": "渡口的报时人，雾里只闻梆子声",
      "from": [
        "原创：把原著里「岸上远远的灯火」拟人化成可拍的角色"
      ]
    }
  ],
  "scenes": [
    {
      "id": "S01",
      "name": "渡船船舱",
      "primary": true
    },
    {
      "id": "S02",
      "name": "渡口栈桥",
      "primary": true
    },
    {
      "id": "S03",
      "name": "对岸芦苇滩",
      "primary": false,
      "reusePlan": "栈桥同一机位换背板，芦苇前景遮挡"
    }
  ],
  "props": [
    {
      "id": "P01",
      "name": "旧皮箱",
      "function": "沈知微的底牌与软肋：里面是一摞状纸和一块灵位。从「谁都不许碰」到当众打开，开箱即翻案——全剧最重的一件物证",
      "beatIds": [
        "B01",
        "B04"
      ]
    },
    {
      "id": "P02",
      "name": "县衙旧砚",
      "function": "陆行远的身份物证：砚底刻着县衙的印。掏出即揭破他不是揣枪的人，压到状纸上即与皮箱合成同一桩冤案",
      "beatIds": [
        "B02",
        "B04"
      ]
    }
  ],
  "beats": [
    {
      "id": "B01",
      "type": "悬念钩",
      "weight": "minor",
      "episode": 1,
      "setup": "皮箱谁都不许碰",
      "payoff": "胡二爷伸手要帮忙拎箱，被沈知微一把按住，全船瞬间安静"
    },
    {
      "id": "B02",
      "type": "身份揭破",
      "weight": "major",
      "episode": 3,
      "setup": "陆行远的右手始终揣在大衣口袋里",
      "payoff": "胡二爷一句玩笑逼得他当众掏出口袋——是一方旧砚，不是枪，可砚底刻着县衙的印"
    },
    {
      "id": "B03",
      "type": "反转",
      "weight": "major",
      "episode": 5,
      "setup": "老周四十年不问客人来路",
      "payoff": "老周头一次开口，点破沈知微要去的县城根本没有接应她的人"
    },
    {
      "id": "B04",
      "type": "收束",
      "weight": "minor",
      "episode": 6,
      "setup": "雾开始散",
      "payoff": "皮箱当众打开，船上每个人的谎都落了地，船也到了岸"
    }
