{
  "source": "验尸官的婚礼",
  "lang": "zh",
  "params": {
    "episodes": 60,
    "minutesPerEpisode": 1.5,
    "genre": "女频大女主复仇悬疑（豪门）",
    "adaptMode": "忠实",
    "preferences": [
      "每集必须拿出一样看得见的证据",
      "结局按选题卡：宋知远伏法、宋婉仪交出沈氏、程野带妹妹自首、林晚当庭改签他杀、墓前放表"
    ]
  },
  "adaptation": {
    "core": "被退婚的女法医每集拿出一样看得见的证据，一层层剥开替身新郎背后的命案，最后亲手推翻自己三年前签下的假报告。",
    "keep": [
      {
        "what": "婚礼上认出替身的开场",
        "why": "全剧卖点就是第一集这一眼，开场必须原样落地",
        "evidence": "一眼认出新郎是替身：真新郎三年前就躺在她的解剖台上。"
      },
      {
        "what": "一集一证据的推进引擎",
        "why": "AI 短剧每集 90 秒，必须有一个能拍特写的实物撑住这一集，证据就是爽点载体",
        "evidence": "每一集她都要拿出一样看得见的证据：一道疤、一张切片、一段录音。"
      },
      {
        "what": "双向逼近：离真相近一步，也离自己的罪近一步",
        "why": "这是女主区别于普通打脸爽剧的地方，赢得越多代价越重，第四幕自曝才立得住",
        "evidence": "也离她自己签过的那份假报告更近一步。"
      },
      {
        "what": "替身识别点：白手套与光洁的虎口",
        "why": "虎口疤是全剧第一件证据，也是程野与沈峥同脸时唯一的视觉区分",
        "evidence": "婚礼上一直戴着白手套，左手虎口光洁，没有疤。"
      },
      {
        "what": "苏曼丽塞房卡、后又反水",
        "why": "给中段一个立场摇摆的变量，防止对抗变成一条直线",
        "evidence": "答谢宴上偷偷把求救的房卡塞给她；为了家里的生意，后面还会反水一次。"
      },
      {
        "what": "结局的签名与表",
        "why": "改签他杀是女主弧的终点，墓前放表是情感收口，两件都不动",
        "evidence": "重新写下“死者沈峥，他杀”，签上自己的名字。最后一场，她把那块表放在沈峥的墓前。"
      }
    ],
    "cut": [
      {
        "what": "林晚与沈砚的感情线",
        "why": "她戴着沈峥的表走完全剧，结局落在墓前；沈砚只做战友和内应，任何新恋情都会冲淡最后一场"
      },
      {
        "what": "港口洗钱的商业操作细节",
        "why": "90 秒一集讲不清资金链，只保留一本账本加一个 U 盘作为实物，其余场外交代"
      },
      {
        "what": "苏家与沈家二房的家族线",
        "why": "苏家只当苏曼丽反水的筹码，二房只当股权动机里的一句话，都不开人物、不开场景"
      },
      {
        "what": "林晚的原生家庭与私生活",
        "why": "她的全部戏都放在证据上，家庭背景不给篇幅"
      }
    ],
    "merge": [
      {
        "what": "接案、收网、押送的各路警察合成一位刑侦队长",
        "why": "警方功能相同，一张脸维护就够"
      },
      {
        "what": "抢档案、调包检材、码头动手的打手合成宋知远的一名保镖",
        "why": "沈家每次毁证据都要有人动手，同一张脸反复出现，观众到第五幕会自己把账算到宋知远头上"
      },
      {
        "what": "婚礼上嘲讽林晚的宾客并入苏曼丽",
        "why": "羞辱集中在一个有名有姓的人身上，后面她塞房卡的反转才有分量"
      }
    ],
    "risks": [
      {
        "what": "逻辑漏洞：未婚妻亲手解剖未婚夫却没认出来",
        "plan": "第 1 幕交代无名男尸面部被螺旋桨毁损且泡水多日，当时沈峥本人正在国外养病、随后就回国露面，没有人会把两件事连起来；她认出替身靠的是虎口疤，不是脸"
      },
      {
        "what": "程野与沈峥同一张脸，AI 生成容易混",
        "plan": "共用一套脸部资产，区分全靠三件事：沈峥左手虎口有疤、只出现在暖色闪回里；程野戴白手套和金丝眼镜，第三幕起摘眼镜"
      },
      {
        "what": "解剖与尸体画面的平台审核尺度",
        "plan": "尸体一律白布覆盖不露脸，证据用档案照片、显微镜下的切片、报告单代替，解剖室只拍器械和林晚的手"
      },
      {
        "what": "女主签过假报告，观众可能不站她",
        "plan": "第 1 幕就闪回逼签现场，交代她当时被周启年用执业资格和三天火化逼到墙角；第四幕她主动自曝、交证，代价自己扛"
      },
